An action of an entity that sets fields of the records selected.

```
use ravenrs_app::{EntityInfo, FieldInfo, FieldKind, RecordAction};

let task = EntityInfo::new("Task")
    .field(FieldInfo::new("id", FieldKind::Integer).key())
    .field(FieldInfo::new("state", FieldKind::Text))
    .action(
        RecordAction::new("Finish")
            .enabled("[state] <> 'done'")
            .set("state = 'done'")
            .confirm("Finish the tasks?"),
    );
assert!(task.check().is_ok());
```

1026.docs:
Something people can do. A handle: the frame and its controller hold the same action, so a
controller can turn it off by a reason of its own.

```
use ravenrs_app::{Action, ActionCategory, CriteriaMode, Selection};

let pay = Action::simple("Pay", "Pagar")
    .category(ActionCategory::Edit)
    .target_entity("Bill")
    .selection(Selection::RequireMultiple)
    .target_criteria("[Status] = 'Open'", CriteriaMode::TrueForAll)
    .on_execute(|cx| {
        for bill in &cx.selected {
            let mut bill = bill.clone();
            bill.set("Status", "Paid");
            cx.space.borrow_mut().save(bill).map_err(|e| e.to_string())?;
        }
        cx.space.borrow_mut().commit().map_err(|e| e.to_string())
    });
assert_eq!(pay.caption(), "Pagar");
```

1032.docs:
What a job sees while it runs, on its own thread.

```
use ravenrs_app::{JobContext, Object};

fn count(job: &JobContext) -> Result<(), String> {
    for (done, record) in job.selected().iter().enumerate() {
        if job.cancelled() {
            return Ok(());
        }
        job.progress((done + 1) as f32 / job.selected().len() as f32, record.entity());
        let mut record = record.clone();
        record.set("Counted", true);
        job.save(record);
    }
    Ok(())
}
# let _ = count;
```

